-- Shared innovation library. Preserve original IDs and PDF evidence; import once.
CREATE TABLE innovations (
 id text PRIMARY KEY NOT NULL,
 title text NOT NULL,
 url text NOT NULL,
 description text NOT NULL,
 pdfs text NOT NULL,
 updated_at text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
 created_at text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL
);
--> statement-breakpoint
CREATE INDEX innovations_updated_at_idx ON innovations(updated_at);
--> statement-breakpoint
CREATE INDEX innovations_created_at_idx ON innovations(created_at);
--> statement-breakpoint
CREATE TABLE innovations_videos (
 _order integer NOT NULL,
 _parent_id text NOT NULL REFERENCES innovations(id) ON DELETE cascade,
 id text PRIMARY KEY NOT NULL,
 url text NOT NULL
);
--> statement-breakpoint
CREATE INDEX innovations_videos_order_idx ON innovations_videos(_order);
--> statement-breakpoint
CREATE INDEX innovations_videos_parent_id_idx ON innovations_videos(_parent_id);
--> statement-breakpoint
CREATE TABLE innovations_materials (
 _order integer NOT NULL,
 _parent_id text NOT NULL REFERENCES innovations(id) ON DELETE cascade,
 id text PRIMARY KEY NOT NULL,
 url text NOT NULL
);
--> statement-breakpoint
CREATE INDEX innovations_materials_order_idx ON innovations_materials(_order);
--> statement-breakpoint
CREATE INDEX innovations_materials_parent_id_idx ON innovations_materials(_parent_id);
--> statement-breakpoint
CREATE TABLE innovations_licenses (
 _order integer NOT NULL,
 _parent_id text NOT NULL REFERENCES innovations(id) ON DELETE cascade,
 id text PRIMARY KEY NOT NULL,
 url text NOT NULL
);
--> statement-breakpoint
CREATE INDEX innovations_licenses_order_idx ON innovations_licenses(_order);
--> statement-breakpoint
CREATE INDEX innovations_licenses_parent_id_idx ON innovations_licenses(_parent_id);
--> statement-breakpoint
CREATE TABLE innovations_categories (
 "order" integer NOT NULL,
 parent_id text NOT NULL REFERENCES innovations(id) ON DELETE cascade,
 value text NOT NULL,
 id integer PRIMARY KEY NOT NULL
);
--> statement-breakpoint
CREATE INDEX innovations_categories_order_idx ON innovations_categories("order");
--> statement-breakpoint
CREATE INDEX innovations_categories_parent_idx ON innovations_categories(parent_id);
--> statement-breakpoint
INSERT INTO innovations (id,title,url,description,pdfs) VALUES ('bawita','BaWita','https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,bawita','INNOWACJA WYBRANA DO UPOWSZECHNIANIA W RAMACH PROJEKTU "INKUBATOR WŁĄCZENIA SPOŁECZNEGO"
1. Na czym polega rozwiązanie?
Narzędzie rehabilitacyjne w postaci drewnianej tablicy wyposażonej w siedem ruchomych elementów służących do wielopłaszczyznowej stymulacji i usprawniania funkcji pamięciowych, manualnych i organizacji dnia dla osób ze schorzeniami dementywnymi.
2. Jakich problemów dotyczy innowacja?
Innowacja odpowiada na problem rozpowszechnianiasię zespołów otępiennych u osób w podeszłym wieku i pozwala zwiększyć ograniczony wachlarz narzędzi rehabilitacyjnych dedykowanych osobom dorosłym.
3. Grupa docelowa
Dorosłe osoby cierpiące na zespół otępienny we wczesnym stadium oraz osoby rehabilitowane pamięciowo po udarach i wylewach.
4. Kto może skorzystać z innowacji?
Placówki wsparcia dziennego seniorów, domy pomocy społecznej, miejskie dzienne domy pomocy społecznej, warsztaty terapii zajęciowej, osoby indywidualne.
5. Czy to działa?
Test innowacji potwierdził jej skuteczność w procesie poprawy pamięci proceduralnej. Wykazał także szereg dodatkowych istotnych dla rehabilitacji osób starszych efektów – poprawa motoryki małej, rozwijanie wyobraźni, skojarzeń, poprawa fluencji i rozbudowywanie pomięci słownej, a nawet poprawa funkcjonowania społecznego i integracji.
6. Autorzy
- Maria Lorenc
- Maciej Parol','[{"url": "https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_BaWita_v15_www.pdf", "pages": [{"page": 1, "text": "„BaWita - tablica manipulacyjna jako dorosła zabawka\nterapeutyczna dla seniorów - plansza manipulacyjna\ndla osób starszych, z chorobami dementywnymi”\n\nMaria Lorenc, Maciej Parol"}, {"page": 2, "text": "1 Jakich problemów dotyczy innowacja\n                                                             społeczna i jakie problemy rozwiązuje?\n                                                           Innowacja odpowiada na problem rozpowszechniania\n                                                           się zespołów otępiennych u osób w podeszłym wieku\n                                                           i pozwala zwiększyć ograniczony wachlarz narzędzi\n                                                           rehabilitacyjnych dedykowanych osobom dorosłym.\n\n\n\n                                                           2 Krótki opis innowacji\n                                                           Narzędzie rehabilitacyjne w postaci drewnianej\n                                                           tablicy wyposażonej w siedem ruchomych elementów\n                                                           służących do wielopłaszczyznowej stymulacji\n                                                           i usprawniania funkcji pamięciowych, manualnych\n                                                           i organizacji dnia dla osób ze schorzeniami\n                                                           dementywnymi.\nProjekt „Inkubator Włączenia Społecznego” realizowany\nprzez Regionalny Ośrodek Polityki Społecznej\nw Krakowie, Fundację Rozwoju Demokracji Lokalnej\nim. Jerzego Regulskiego i Centrum Ewaluacji i Analiz\nPolityk Publicznych UJ, wdrażany w ramach IV Osi\nPriorytetowej Programu Operacyjnego Wiedza\nEdukacja Rozwój (Działanie 4.1: Innowacje społeczne), na\nzlecenie Ministerstwa Funduszy i Polityki Regionalnej,\nfinansowany jest ze środków Unii Europejskiej w ramach\nEuropejskiego Funduszu Społecznego."}, {"page": 3, "text": "3 Grupa docelowa                                    Scenariusze zajęć warsztatowych dla\n                                                    opiekuna/fizjoterapeuty\nDorosłe osoby cierpiące na zespół otępienny we\nwczesnym stadium oraz osoby rehabilitowane\npamięciowo po udarach i wylewach.\n\n\n\n4 Elementy innowacji\n            Projekt wykonawczy tablicy wraz\n            z projektem wymiennych elementów\n\n\n\n\n                                                 5 Kto może skorzystać z innowacji?\n                                                 Placówki wsparcia dziennego seniorów, domy\n                                                 pomocy społecznej, miejskie dzienne domy pomocy\n                                                 społecznej, warsztaty terapii zajęciowej, osoby\n                                                 indywidualne."}, {"page": 4, "text": "7 O Autorach\n\n                                                                                Maria Lorenc\n                                                                                Z wykształcenia pedagog\n                                                                                społeczny, zawsze pociągało\n                                                                                ją zagadnienie różnorodności\n                                                                                kulturowej. Zawodowo zajmuje\n                                                                                się rozwojem pracowników oraz\n                                                                                badaniem środowiska pracy.\n                                                                                Od kilku lat wspiera i angażuje\n                                                                                się w realizację różnorodnych\n                                                                                działań aktywizujących\n                                                                                społecznie.\n\n\n\n\n6 Czy to działa?                                           Maciej Parol\nTest innowacji potwierdził jej skuteczność w procesie      Jego pasją jest tworzenie\npoprawy pamięci proceduralnej. Wykazał także               funkcjonalnych i naturalnych\nszereg dodatkowych istotnych dla rehabilitacji             przedmiotów codziennego\nosób starszych efektów – poprawa motoryki małej,           użytku z drewna, od zabawek\nrozwijanie wyobraźni, skojarzeń, poprawa fluencji          po meble. Jako wolontariusz\ni rozbudowywanie pomięci słownej, a nawet poprawa          zaangażował się we wsparcie\nfunkcjonowania społecznego i integracji.                   osób starszych. Przy\n                                                           projekcie tablicy wykorzystał\n    Mnie wszystko dobrze wychodziło, tylko trudne          doświadczenie nabyte\n    były zatrzaski, ale dużo zapamiętałam. (...) Jak       w kontaktach z podopiecznymi\n    córka przyjedzie, jak ta tablica będzie, to ja jej     i zamiłowanie do pracy\n    pokażę i to się pochwalę, że umiem to robić.           z drewnem.\n                                                Testerka"}, {"page": 5, "text": "Zapraszamy do kontaktu\n    z Działem Innowacji Społecznych\nRegionalnego Ośrodka Polityki Społecznej\n               w Krakowie\n\n\n\n\n          Zadzwoń: 12 422 06 36\n      Napisz: biuro@rops.krakow.pl\n  Śledź aktualności: www.rops.krakow.pl"}]}]');
--> statement-breakpoint
