INSERT INTO innovations (id,title,url,description,pdfs) VALUES ('merkury','Merkury','https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,merkury','INNOWACJA WYBRANA DO UPOWSZECHNIANIA W RAMACH PROJEKTU "INKUBATOR WŁĄCZENIA SPOŁECZNEGO"
1. Na czym polega rozwiązanie?
Platforma internetowa umożliwiająca dostęp do symulatora czterech urządzeń samoobsługowych (bankomat, parkomat, paczkomat oraz kasa samoobsługowa), dająca możliwość przetestowania jego obsługi w bezpiecznych, domowych warunkach. Wspiera seniorów w samodzielnej obsłudze tych urządzeń w przestrzeni publicznej ponosząc ich kompetencje cyfrowe.
2. Jakich problemów dotyczy innowacja?
Innowacja odpowiada na niskie kompetencje seniorów związane z obsługą rozwiązań technologicznych, a w efekcie na obawy przed skorzystaniem z kiosków samoobsługowych (np. paczkomatu, bankomatu).
3. Grupa docelowa
Osoby starsze, którym towarzyszy strach i niepewność przy korzystaniu z urządzeń samoobsługowych.
4. Kto może skorzystać z innowacji?
Organizacje pozarządowe wspierające aktywność seniorów, dzienne domy pomocy społecznej, kluby seniora.
5. Czy to działa?
Narzędzie trafnie odpowiada na problem pozwalając na szerszą adaptację seniorów do nowych, zinformatyzowanych elementów przestrzeni publicznej. Daje możliwość oswojenia się z obsługą urządzeń i zredukowanie obaw przed skorzystaniem z kiosków samoobsługowych w codziennym życiu.
6. Autorzy
Stowarzyszenie Edukacji Pozaformalnej „Meritum”
- Bartosz Kosiński
- Mirosław Bohatkiewicz​','[{"url": "https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_Merkury_v4_www.pdf", "pages": [{"page": 1, "text": "„Merkury – symulator kiosków samoobsługowych”\n\nStowarzyszenie Edukacji Pozaformalnej\n„Meritum”"}, {"page": 2, "text": "1 Jakich problemów dotyczy innowacja\n                                                             społeczna i jakie problemy rozwiązuje?\n                                                           Innowacja odpowiada na niskie kompetencje seniorów\n                                                           związane z obsługą rozwiązań technologicznych,\n                                                           a w efekcie na obawy przed skorzystaniem z kiosków\n                                                           samoobsługowych (np. paczkomatu, bankomatu).\n\n\n                                                           2 Krótki opis innowacji\n                                                           Platforma internetowa umożliwiająca dostęp do\n                                                           symulatora czterech urządzeń samoobsługowych\n                                                           (bankomat, parkomat, paczkomat oraz kasa\n                                                           samoobsługowa), dająca możliwość przetestowania\n                                                           jego obsługi w bezpiecznych, domowych warunkach.\n                                                           Wspiera seniorów w samodzielnej obsłudze tych\nProjekt „Inkubator Włączenia Społecznego” realizowany      urządzeń w przestrzeni publicznej ponosząc ich\nprzez Regionalny Ośrodek Polityki Społecznej               kompetencje cyfrowe.\nw Krakowie, Fundację Rozwoju Demokracji Lokalnej\nim. Jerzego Regulskiego i Centrum Ewaluacji i Analiz\nPolityk Publicznych UJ, wdrażany w ramach IV Osi\nPriorytetowej Programu Operacyjnego Wiedza\nEdukacja Rozwój (Działanie 4.1: Innowacje społeczne), na\nzlecenie Ministerstwa Funduszy i Polityki Regionalnej,\nfinansowany jest ze środków Unii Europejskiej w ramach\nEuropejskiego Funduszu Społecznego."}, {"page": 3, "text": "3 Grupa docelowa\nOsoby starsze, którym towarzyszy strach i niepewność\nprzy korzystaniu z urządzeń samoobsługowych.\n\n\n\n4 Elementy innowacji\n                Kod źródłowy platformy\n\n\n\n\n                                                       5 Kto może skorzystać z innowacji?\n                                                       Organizacje pozarządowe wspierające aktywność\n                                                       seniorów, dzienne domy pomocy społecznej, kluby\n                                                       seniora.\n\n\n\n\n                                                       6 Czy to działa?\n                                                       Narzędzie trafnie odpowiada na problem pozwalając\n                                                       na szerszą adaptację seniorów do nowych,\n                                                       zinformatyzowanych elementów przestrzeni\n                                                       publicznej. Daje możliwość oswojenia się z obsługą\n                                                       urządzeń i zredukowanie obaw przed skorzystaniem\n                                                       z kiosków samoobsługowych w codziennym życiu."}, {"page": 4, "text": "7 O Autorach\n                                                    Stowarzyszenie Edukacji Pozaformalnej „Meritum”\n\n\n\n\n                                                                     Bartosz Kosiński\n                                                                     Od ponad 15 lat uczy i opracowuje\n                                                                     modele nauczania kompetencji\n                                                                     cyfrowych z wykorzystaniem\n                                                                     różnych narzędzi. Tworzy gry\n                                                                     edukacyjne (cyfrowe i planszowe).\n                                                                     Autor innowacji edukacyjnych,\n                                                                     związanych z rozwojem kompetencji\n                                                                     cyfrowych.\n\n\n\n\nNiestety problem jest aktualny. Wydawałoby\nsię, że bankomaty czy paczkomaty, że to\nwszystko jest już z nami od lat i młodzi ludzie                      Mirosław Bohatkiewicz\nwskakują w to, praktycznie bez żadnego                               Software Developer, w wolnym\nproblemu. Natomiast seniorzy mają tę                                 czasie prowadzi zajęcia\nblokadę, mają tę blokadę przed nowościami,                           dydaktyczne z programowania\nmają tę blokadę takiego strachu, że „co będzie,                      w Javie dla młodzieży. Absolwent\njak mi kartę porwie?”, trochę demonizują                             Wytwarzania Mechatronicznego\nte wszystkie nowinki technologiczne i tak                            na Akademii Górniczo-Hutniczej,\nnaprawdę dopóki dobrze nie poznają tego, to                          studiuje Game Design na Wyższej\nmają barierę, żeby z tego korzystać i jeszcze                        Szkole Europejskiej im. Ks. Józefa\nużywać tego samodzielnie.                                            Tischnera.\n\n                 Trenerka kompetencji cyfrowych,\n                   prowadząca zajęcia z seniorami"}, {"page": 5, "text": "Zapraszamy do kontaktu\n    z Działem Innowacji Społecznych\nRegionalnego Ośrodka Polityki Społecznej\n               w Krakowie\n\n\n\n          Zadzwoń: 12 422 06 36\n      Napisz: biuro@rops.krakow.pl\n  Śledź aktualności: www.rops.krakow.pl"}]}]');
