INSERT INTO innovations (id,title,url,description,pdfs) VALUES ('gluchy-czytelnik-w-bibliotece','Głuchy czytelnik w bibliotece','https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,gluchy-czytelnik-w-bibliotece','INNOWACJA WYBRANA DO UPOWSZECHNIANIA W RAMACH PROJEKTU "INKUBATOR WŁĄCZENIA SPOŁECZNEGO"
1. Na czym polega rozwiązanie?
Publikacja przybliżająca osobom g/Głuchym instytucję jaką jest biblioteka oraz pokazująca, że czytanie jest ważne. Publikacja powstała w polskim języku migowym, a następnie została przełożona na łatwy tekst w języku polskim. Publikacja daje wskazówki jak wspierać dziecko w czytaniu i jak korzystać z biblioteki.
2. Jakich problemów dotyczy innowacja?
Innowacja jest odpowiedzią na potrzebę włączenia osób g/Głuchych do społeczności czytelników korzystających z usług bibliotek.
3. Grupa docelowa
Osoby g/Głuche, szczególnie rodzice, którzy posiadają dzieci w wieku szkolnym, zarówno słyszące (KODA), jak i dzieci g/Głuche oraz słabosłyszące.
4. Kto może skorzystać z innowacji?
Biblioteki publiczne, biblioteki szkolne, szkoły integracyjne.
5. Czy to działa?
Publikacja ułatwia osobom g/Głuchym dostęp do bibliotek, wyjaśnia sposób ich działania i mobilizuje do korzystania z nich. Może realnie wpłynąć na jakość życia g/Głuchych rodziców, a przede wszystkim ich dzieci.
6. Autorki
dr Dominika Wiśniewska
Anna Antos','[{"url": "https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_GuchyCzytelnik_v4_www.pdf", "pages": [{"page": 1, "text": "„Głuchy czytelnik w bibliotece”\n\nDominika Wiśniewska, Anna Antos"}, {"page": 2, "text": "1 Jakich problemów dotyczy innowacja\n                                                             społeczna i jakie problemy rozwiązuje?\n                                                           Innowacja jest odpowiedzią na potrzebę włączenia\n                                                           osób g/Głuchych do społeczności czytelników\n                                                           korzystających z usług bibliotek.\n\n\n\n\n                                                           2 Krótki opis innowacji\n                                                           Publikacja przybliżająca osobom g/Głuchym instytucję\n                                                           jaką jest biblioteka oraz pokazująca, że czytanie\n                                                           jest ważne. Publikacja powstała w polskim języku\n                                                           migowym, a następnie została przełożona na łatwy\n                                                           tekst w języku polskim. Publikacja daje wskazówki jak\n                                                           wspierać dziecko w czytaniu i jak korzystać z biblioteki.\nProjekt „Inkubator Włączenia Społecznego” realizowany\nprzez Regionalny Ośrodek Polityki Społecznej\nw Krakowie, Fundację Rozwoju Demokracji Lokalnej\nim. Jerzego Regulskiego i Centrum Ewaluacji i Analiz\nPolityk Publicznych UJ, wdrażany w ramach IV Osi\nPriorytetowej Programu Operacyjnego Wiedza\nEdukacja Rozwój (Działanie 4.1: Innowacje społeczne), na\nzlecenie Ministerstwa Funduszy i Polityki Regionalnej,\nfinansowany jest ze środków Unii Europejskiej w ramach\nEuropejskiego Funduszu Społecznego."}, {"page": 3, "text": "3 Grupa docelowa\nOsoby g/Głuche, szczególnie rodzice, którzy posiadają\ndzieci w wieku szkolnym, zarówno słyszące (KODA), jak\ni dzieci g/Głuche oraz słabosłyszące.\n\n\n\n4 Elementy innowacji\nPublikacja w formacie PDF zawierająca filmy,\nw których treść poszczególnych rozdziałów jest\nwyrażona w polskim języku migowym.\n\n\n\n    Tematy znajdujące się w publikacji to:\n\n\n     jak wspomagać czytanie dzieci\n     (szczególnie słyszących dzieci g/Głuchych\n     rodziców)\n\n     opis roli jaką pełnią biblioteki\n\n     instrukcja założenia konta w bibliotece\n\n     słownik definicji/pojęć\n\n\n                                                        5 Kto może skorzystać z innowacji?\n                                                        Biblioteki publiczne, biblioteki szkolne, szkoły\n                                                        integracyjne."}, {"page": 4, "text": "7 O Autorach\n                                                                                    dr Dominika Wiśniewska\n                                                                                    niesłyszący psycholog,\n                                                                                    psychoterapeuta, wykładowca\n                                                                                    akademicki w Akademii\n                                                                                    Pedagogiki Specjalnej im.\n                                                                                    M. Grzegorzewskiej, członek\n                                                                                    Zespołu Ekspertów ds. Osób\n                                                                                    g/Głuchych przy Rzeczniku\n                                                                                    Praw Obywatelskich,\n                                                                                    autorka: programów\n                                                                                    psychoedukacyjnych dla dzieci\n                                                                                    niesłyszących, warsztatów dla\n                                                                                    rodziców dzieci z wadą słuchu,\n                                                                                    innowacji społecznych.\n\n6 Czy to działa?\nPublikacja ułatwia osobom g/Głuchym dostęp do                  Anna Antos\nbibliotek, wyjaśnia sposób ich działania i mobilizuje\ndo korzystania z nich. Może realnie wpłynąć na jakość          niesłyszący surdopedagog, nauczyciel-bibliotekarz\nżycia g/Głuchych rodziców, a przede wszystkim ich              w Ośrodku Szkolno-Wychowawczym dla g/Głuchych\ndzieci.                                                        w Warszawie. Autorka książek „Życie i osiągnięcia\n                                                               naukowe prof. dr hab. Włodzimierza Pietrzaka” oraz\n                                                               „Maria Góralówna”, a także artykułów w publikacjach\n                                                               surdopedagogicznych. Jako inspektor ds. ochrony\n     Nawet ci rodzice, którzy nie znają języka                 zwierząt podejmowała interwencje niosąc pomoc\n     polskiego mogliby zobaczyć tłumaczenie                    poszkodowanym czworonogom.\n     i razem z dziećmi usiąść do książki. Rodzice\n     nieznający języka boją się zbliżyć do książki.\n\n                                                      Tester"}, {"page": 5, "text": "Zapraszamy do kontaktu\n    z Działem Innowacji Społecznych\nRegionalnego Ośrodka Polityki Społecznej\n               w Krakowie\n\n\n\n\n          Zadzwoń: 12 422 06 36\n      Napisz: biuro@rops.krakow.pl\n  Śledź aktualności: www.rops.krakow.pl"}]}]');
